    def __init__(self, agent_id=None):
        # 员工身份：命令行参数优先，其次环境变量
        self.agent_id = (
            agent_id
            or (sys.argv[1] if len(sys.argv) > 1 else None)
            or os.environ.get('AGENT_ID', 'unknown')
        )

        # 家目录与运行时根目录
        self.home = os.environ.get('HOME', os.path.expanduser('~'))

        # 运行模式: local | collaborative | order
        self.run_mode = os.environ.get('AGENT_RUN_MODE', 'local')
        if self.run_mode not in ('local', 'collaborative', 'order'):
            self.run_mode = 'local'
        self.runtime_home = os.environ.get(
            'AGENT_RUNTIME_HOME', os.path.join(self.home, '.openchiip-harness', 'data'))

        # LLM 配置（agent.env 注入）
        self.model_server = os.environ.get('MODEL_SERVER', '').rstrip('/')
        self.model_name = os.environ.get('MODEL_NAME', '')
        self.fast_model_name = os.environ.get('FAST_MODEL_NAME', 'ernie-4.5-turbo-128k')
        self.llm_api_key = os.environ.get('LLM_API_KEY', '')

        # HTTP 服务端口
        self.port = int(os.environ.get('AGENT_PORT', '18100'))

        # CHIIP 管理后端地址（心跳上报/A2A 发现），默认平台地址
        self.backend_url = os.environ.get('CHIIP_BACKEND_URL', '').rstrip('/')
        self.backend_token = os.environ.get('CHIIP_BACKEND_TOKEN', '')

        # WebSocket 连接配置
        self.ws_url = os.environ.get('AGENT_WS_URL', '').rstrip('/')
        self.ws_token = os.environ.get('AGENT_WS_TOKEN', '') or self.backend_token

        # 代码内置技能目录（随代码分发，全员共享）
        self.base_dir = Path(__file__).resolve().parent.parent
        self.skills_builtin_dir = self.base_dir / 'skills'
        self.tools_builtin_dir = self.base_dir / 'tools'
        self.metaskills_builtin_dir = self.base_dir / 'metaskills'

        # 员工专属运行时目录
        self.skills_user_dir = Path(self.runtime_home) / 'skills'
        self.metaskills_user_dir = Path(self.runtime_home) / 'metaskills'
        self.memory_dir = Path(self.runtime_home) / 'memory'
        self.long_term_dir = self.memory_dir / 'long_term'
        self.execution_log_dir = self.memory_dir / 'execution_logs'
        self.archive_dir = self.memory_dir / 'archive'
        self.a2a_dir = Path(self.runtime_home) / 'a2a'

        # SQLite 数据库路径
        self.db_file = Path(self.runtime_home) / 'agent.db'

        # 运行时文件
        self.config_file = Path(self.runtime_home) / 'config.json'
        self.tools_file = Path(self.runtime_home) / 'tools.json'  # 后端下发的已安装工具
        self.pid_file = Path(self.runtime_home) / 'agent.pid'
        self.short_term_file = self.memory_dir / 'short_term.jsonl'
        self.history_file = Path(self.runtime_home) / 'history.jsonl'  # 兼容旧格式
        self.token_meter_file = self.memory_dir / 'token_meter.json'
        self.intent_cache_file = self.memory_dir / 'intent_cache.json'
        self.fallback_log_file = self.memory_dir / 'fallback_log.jsonl'
        self.lessons_file = self.long_term_dir / 'lessons_learned.jsonl'
        self.agent_card_file = self.a2a_dir / 'agent_card.json'

        # 工作区目录配置（可被 config.json 覆盖）
        home = Path(self.home)
        self.workspace_dirs = [
            {'label': '工作区', 'path': str(home / 'workspace')},
            {'label': '家目录', 'path': self.home},
            {'label': '文档', 'path': str(home / 'documents')},
            {'label': '共享目录', 'path': '/home/shared'},
            {'label': '临时目录', 'path': str(home / 'tmp')},
        ]

        # 运行参数（可被 config.json 覆盖）
        self.params = dict(self.DEFAULTS)

        # SQLite 凭据加载（优先级高于环境变量）
        self.has_credentials = False
        self._load_credentials_from_db()

        self._load_overrides()

    # ─────────────────────────────────────────
    # SQLite 凭据加载（优先级高于 agent.env 环境变量）
    # ─────────────────────────────────────────
    def _load_credentials_from_db(self):
        """从 SQLite 加载持久化凭据（覆盖环境变量）。"""
        try:
            import sqlite3
            if not self.db_file.exists():
                return
            conn = sqlite3.connect(str(self.db_file), timeout=5)
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            # 检查 credentials 表是否存在
            cur.execute(
                "SELECT name FROM sqlite_master "
                "WHERE type='table' AND name='credentials'")
            if not cur.fetchone():
                conn.close()
                return
            cur.execute('SELECT key, value FROM credentials')
            creds = {row[0]: row[1] for row in cur.fetchall()}
            conn.close()
            if not creds.get('token'):
                return
            # SQLite 凭据覆盖环境变量
            self.agent_id = creds.get('agent_id', self.agent_id)
            self.ws_token = creds.get('token', '') or self.ws_token
            self.backend_url = creds.get('platform_url', '') or self.backend_url
            self.ws_url = creds.get('ws_url', '') or self.ws_url
            self.has_credentials = True
        except Exception:
            pass  # SQLite 未就绪或损坏，安全回退

    # ─────────────────────────────────────────
    # 配置覆盖
    # ─────────────────────────────────────────
    def _load_overrides(self):
        """读取 {RUNTIME_HOME}/config.json 覆盖默认参数与环境配置。"""
        if not self.config_file.exists():
            return
        try:
            data = json.loads(self.config_file.read_text(encoding='utf-8'))
        except (ValueError, OSError):
            return
        for key, val in data.items():
            if key == 'run_mode':
                # run_mode 既是 params 键，也是直接属性，需同步更新
                if val in ('local', 'collaborative', 'order'):
                    self.params[key] = val
                    self.run_mode = val
                    logger.info('config.json 加载 run_mode: %s', val)
            elif key in self.params:
                self.params[key] = val
            elif key == 'model_server':
                self.model_server = str(val).rstrip('/')
            elif key == 'model_name':
                self.model_name = val
            elif key == 'fast_model_name':
                self.fast_model_name = val
            elif key == 'backend_url':
                self.backend_url = str(val).rstrip('/')
            elif key == 'workspace_dirs' and isinstance(val, list):
                self.workspace_dirs = [
                    {'label': d.get('label', ''), 'path': d.get('path', '')}
                    for d in val if d.get('path')
                ]

    def get(self, key, default=None):
        return self.params.get(key, default)

    def save(self, updates: dict = None) -> bool:
        """将运行参数持久化到 {RUNTIME_HOME}/config.json。

        Args:
            updates: 可选的增量覆盖字典（仅接受 DEFAULTS 中已声明的键）。

        保留配置文件中已有的非 params 键（如 model_server / model_name），
        再用当前内存中的 params 覆盖后整体写回。写入失败返回 False。
        """
        if updates:
            for key, val in updates.items():
                if key in self.params:
                    self.params[key] = val

        payload = {}
        # 保留既有配置文件中的其他键（凭据/模型服务地址等）
        if self.config_file.exists():
            try:
                existing = json.loads(self.config_file.read_text(encoding='utf-8'))
                if isinstance(existing, dict):
                    payload.update(existing)
            except (ValueError, OSError):
                pass
        payload.update(self.params)

        try:
            Path(self.runtime_home).mkdir(parents=True, exist_ok=True)
            self.config_file.write_text(
                json.dumps(payload, ensure_ascii=False, indent=2),
                encoding='utf-8')
            return True
        except OSError:
            return False

    @property
    def llm_configured(self):
        return bool(self.model_server and self.model_name and self.llm_api_key)

    @property
    def fast_model_configured(self):
        return bool(self.model_server and self.fast_model_name and self.llm_api_key)

    def ensure_dirs(self):
        """创建运行时目录结构（init_workspace 调用）。"""
        home = Path(self.home)
        for d in (self.runtime_home, self.skills_user_dir, self.memory_dir,
                  self.long_term_dir, self.execution_log_dir, self.archive_dir,
                  self.a2a_dir, self.metaskills_user_dir,
                  # 工作区基础目录（无条件创建）
                  home / 'workspace',
                  home / 'workspace' / 'projects',
                  home / 'workspace' / 'projects' / 'proj-default',
                  home / 'workspace' / 'projects' / 'proj-default' / 'tasks',
                  home / 'workspace' / 'projects' / 'proj-default' / 'repos',
                  ):
            Path(d).mkdir(parents=True, exist_ok=True)
        # 创建工作区目录（仅当父目录存在时）
        for wd in self.workspace_dirs:
            wd_path = Path(wd['path'])
            if wd_path.parent.exists() and not wd_path.exists():
                try:
                    wd_path.mkdir(parents=True, exist_ok=True)
                except OSError:
                    pass  # 无权限创建则跳过
